cssCode:
.booking-btn {
  position: relative; overflow: hidden;
  padding: 15px 35px; font-size: 16px; font-weight: bold;
  color: #d4af37; background: transparent;
  border: 2px solid #d4af37; border-radius: 30px;
  cursor: pointer; transition: color 0.4s ease;
  font-family: sans-serif; letter-spacing: 1px;
}
.booking-btn::before {
  content: ""; position: absolute;
  top: 0; left: -100%; width: 100%; height: 100%;
  background: #d4af37; z-index: -1;
  transition: transform 0.5s cubic-bezier(0.19, 1, 0.22, 1);
}
.booking-btn:hover, .booking-btn:active {
  color: #000; box-shadow: 0 0 20px rgba(212, 175, 55, 0.5);
}
.booking-btn:hover::before, .booking-btn:active::before {
  transform: translateX(100%);
}

